import React from "react";
import { random } from "remotion";
import { palette } from "../theme/palette";
import { Dome, archPath, cuspedArchPath } from "./WeddingDaySets";
import { GarlandSwag, MarigoldStrand } from "../props/Florals";

/*
 * The baraat street: a row of painted haveli facades with arched doorways and jharokhas,
 * and a floral welcome gate. Scene space; `base` is the street line.
 */

const WALLS = ["#E9CBA3", "#E2B7A0", "#EBD6B4", "#DDB58E", "#E6C2AE"];

export const Haveli: React.FC<{ x: number; w: number; h: number; base: number; wall: string; seed: string }> = ({ x, w, h, base, wall, seed }) => {
  const top = base - h;
  const shade = "#000";
  const doorW = w * 0.34;
  const winW = w * 0.2;
  const hasDome = random(`${seed}d`) > 0.5;
  const trim = palette.ivoryLight;
  const lit = "#F6DDB0";
  return (
    <g>
      {/* parapet */}
      {new Array(Math.floor(w / 22)).fill(0).map((_, i) => (
        <path key={i} d={`M${x + i * 22 + 4} ${top} L${x + i * 22 + 4} ${top - 10} Q${x + i * 22 + 11} ${top - 18} ${x + i * 22 + 18} ${top - 10} L${x + i * 22 + 18} ${top} Z`} fill={wall} />
      ))}
      {hasDome ? (
        <g>
          <rect x={x + w / 2 - 34} y={top - 40} width={68} height={40} fill={wall} />
          <Dome cx={x + w / 2} by={top - 40} w={80} h={56} fill={wall} finial={palette.gold} />
        </g>
      ) : null}
      <rect x={x} y={top} width={w} height={h} fill={wall} />
      <rect x={x} y={top} width={w} height={h} fill={shade} opacity={0.04} />
      <rect x={x + w - 14} y={top} width={14} height={h} fill={shade} opacity={0.1} />
      <rect x={x} y={top + 6} width={w} height={4} fill={trim} opacity={0.8} />
      <rect x={x} y={base - h * 0.44} width={w} height={8} fill={trim} opacity={0.75} />
      <rect x={x} y={base - h * 0.44 + 8} width={w} height={3} fill={palette.gold} opacity={0.6} />
      {/* painted frieze */}
      {new Array(Math.floor(w / 26)).fill(0).map((_, i) => (
        <circle key={i} cx={x + 13 + i * 26} cy={top + 26} r={3.5} fill={palette.maroonLight} opacity={0.5} />
      ))}
      {/* upper jharokhas */}
      {[0.25, 0.75].map((k) => {
        const wx = x + w * k - winW / 2;
        const wy = top + h * 0.2;
        return (
          <g key={k}>
            <path d={`M${wx - 10} ${wy + winW * 1.5} L${wx + winW + 10} ${wy + winW * 1.5} L${wx + winW} ${wy + winW * 1.5 + 16} L${wx} ${wy + winW * 1.5 + 16} Z`} fill={trim} />
            <path d={archPath(wx, winW, wy + winW * 0.6, wy, wy + winW * 1.5)} fill={lit} />
            <path d={archPath(wx, winW, wy + winW * 0.6, wy, wy + winW * 1.5)} fill="none" stroke={trim} strokeWidth={5} />
            <rect x={wx} y={wy + winW} width={winW} height={winW * 0.5} fill="url(#jali)" opacity={0.6} />
            <Dome cx={wx + winW / 2} by={wy - 6} w={winW + 16} h={winW * 0.5} fill={trim} />
          </g>
        );
      })}
      {/* arched doorway */}
      <path d={cuspedArchPath(x + w / 2 - doorW / 2, doorW, base - h * 0.28, base - h * 0.4, base, 5)} fill="#8C5A3C" opacity={0.85} />
      <path d={cuspedArchPath(x + w / 2 - doorW / 2, doorW, base - h * 0.28, base - h * 0.4, base, 5)} fill="none" stroke={trim} strokeWidth={6} />
      <rect x={x + w / 2 - 0.8} y={base - h * 0.28} width={1.6} height={h * 0.28} fill={palette.goldDeep} opacity={0.6} />
    </g>
  );
};

/** A continuous row of havelis from x0 to x1. */
export const HaveliRow: React.FC<{ x0: number; x1: number; base: number; seed: string; hMin?: number; hMax?: number }> = ({ x0, x1, base, seed, hMin = 400, hMax = 540 }) => {
  const items: React.ReactNode[] = [];
  let x = x0;
  let i = 0;
  while (x < x1) {
    const w = 220 + random(`${seed}w${i}`) * 90;
    const h = hMin + random(`${seed}h${i}`) * (hMax - hMin);
    items.push(<Haveli key={i} x={x} w={w} h={h} base={base} wall={WALLS[(i + Math.floor(random(seed) * 5)) % WALLS.length]} seed={`${seed}${i}`} />);
    x += w;
    i++;
  }
  return <g>{items}</g>;
};

/** Floral welcome gate over the street: two pillars, a scalloped arch, marigold ladis. */
export const WelcomeGate: React.FC<{ cx: number; base: number; w: number; h: number; seed: string; sway?: number }> = ({ cx, base, w, h, seed, sway = 0 }) => {
  const x0 = cx - w / 2;
  const x1 = cx + w / 2;
  const top = base - h;
  return (
    <g>
      {[x0, x1].map((x) => (
        <g key={x}>
          <rect x={x - 16} y={top + 30} width={32} height={h - 30} fill={palette.ivoryLight} />
          <rect x={x - 16} y={top + 30} width={9} height={h - 30} fill={palette.ivoryShade} />
          {new Array(Math.floor((h - 60) / 70)).fill(0).map((_, i) => (
            <rect key={i} x={x - 18} y={top + 80 + i * 70} width={36} height={6} fill={palette.gold} />
          ))}
          <path d={`M${x - 24} ${top + 30} L${x + 24} ${top + 30} L${x + 18} ${top + 14} L${x - 18} ${top + 14} Z`} fill={palette.gold} />
          <rect x={x - 22} y={base - 20} width={44} height={20} fill={palette.gold} />
        </g>
      ))}
      <path d={`M${x0 - 30} ${top + 14} L${x1 + 30} ${top + 14} L${x1 + 30} ${top - 26} L${x0 - 30} ${top - 26} Z`} fill={palette.maroon} />
      <rect x={x0 - 30} y={top - 26} width={w + 60} height={4} fill={palette.goldLight} />
      <rect x={x0 - 30} y={top + 10} width={w + 60} height={4} fill={palette.goldLight} />
      <path d={`M${cx - 40} ${top - 26} C${cx - 30} ${top - 60} ${cx + 30} ${top - 60} ${cx + 40} ${top - 26} Z`} fill={palette.maroon} />
      <circle cx={cx} cy={top - 44} r={8} fill="url(#foil)" />
      <GarlandSwag from={[x0 - 20, top + 16]} to={[cx, top + 16]} sag={28} r={11} seed={`${seed}a`} />
      <GarlandSwag from={[cx, top + 16]} to={[x1 + 20, top + 16]} sag={28} r={11} seed={`${seed}b`} />
      {[0.12, 0.3, 0.7, 0.88].map((k, i) => (
        <MarigoldStrand key={k} x={x0 + w * k} y={top + 16} length={120 + (i % 2) * 70} r={9} seed={`${seed}s${i}`} sway={sway} />
      ))}
    </g>
  );
};
